// BEREITS FERTIG – nicht verändern
const subscribers = $input.first().json.subscribers;
if (!Array.isArray(subscribers)) {
  throw new Error("Feld 'subscribers' fehlt. Der Node 'Ergebnisse sammeln' bekommt keine Daten. Sind alle vier Aufgaben-Nodes konfiguriert?");
}
const actualNames = subscribers.map(s => s.name);
const expectedNames = ['Frank Hoffmann', 'Clara Weber', 'Greta Lange', 'Anna Müller', 'Xenia Herrmann'];

const hinweise = [];
const teilnehmer = String($('AUFGABE 0 – Namen eintragen').first().json.name || '').trim();
if (!teilnehmer) hinweise.push('AUFGABE 0: Euer Name fehlt. Tragt ihn im ersten Node ein, sonst landet nichts im Scoreboard.');
if (subscribers.length !== 5) hinweise.push(`Es kommen ${subscribers.length} statt 5 Einträge an. Aufgabe 4 (Limit) prüfen.`);
if (subscribers.some(s => s.active !== true)) hinweise.push("Es sind inaktive Abonnenten dabei. Aufgabe 2 (Filter) prüfen.");
if (new Set(subscribers.map(s => s.email)).size !== subscribers.length) hinweise.push("Es sind doppelte E-Mail-Adressen dabei. Aufgabe 1 (Remove Duplicates, Feld 'email') prüfen.");
if (actualNames[0] !== 'Frank Hoffmann') hinweise.push("An erster Stelle steht nicht Frank Hoffmann. Aufgabe 3 (Sort): erst 'opens_per_month', dann 'signup_date', beide Descending.");
const correct = hinweise.length === 0 && expectedNames.every((n, i) => actualNames[i] === n);
if (hinweise.length === 0 && !correct) hinweise.push("Die Reihenfolge stimmt noch nicht. Zweites Sortierfeld 'signup_date' (Descending) prüfen.");

return [{
  json: {
    timestamp:       new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
    korrekt:         correct ? '✅ Ja' : '❌ Nein',
    hinweise:        hinweise.length ? hinweise.join(' | ') : 'Alles richtig!',
    anzahl_ergebnis: subscribers.length,
    erster_kontakt:  actualNames[0] || '-',
    alle_namen:      actualNames.join(', ')
  }
}];
